sys_variable_value.value:
/**
 * Safety-net triage for bfd_flow_case_intake.
 * The before-insert business rules normally triage the case; this only acts
 * when risk_score is still empty.
 */
(function execute(inputs, outputs) {
    var result = new bfd_FlowSupport().safetyNetTriage(inputs.caseSysId);
    outputs.triaged = result.triaged ? 'true' : 'false';
    outputs.riskLevel = result.riskLevel || '';
    outputs.priority = result.priority || '';
})(inputs, outputs);

